from pathlib import Path
from datetime import datetime
import json
B=Path(__file__).resolve().parents[1];E=B/'evidence'
def iso(s):return datetime.fromisoformat(s.replace('Z','+00:00'))
data=json.loads((E/'data-validation.json').read_text(encoding='utf-8'))
normal=json.loads((E/'airflow-backfill__2025-12-07T00_00_00+00_00.json').read_text(encoding='utf-8'))
tasks=normal['tasks'];rt=normal['run'];timings=[]
for task,label in [('attendre_bronze','Attendre Bronze'),('silver_trajets','Spark Silver'),('controle_qualite','Contrôle qualité')]:
    t=next(t for t in tasks if t['task_id']==task);timings.append([label,f"{t['duration']:.2f} s",'Succès'])
gold=[t for t in tasks if t['task_id'].startswith('dbt_gold.')]
elapsed=(max(iso(t['end_date']) for t in gold)-min(iso(t['start_date']) for t in gold)).total_seconds()
timings.append(['Groupe dbt Gold et tests',f'{elapsed:.2f} s','Succès avec WARN métier'])
t=next(t for t in tasks if t['task_id']=='publier');timings.append(['Publication Asset',f"{t['duration']:.2f} s",'Succès'])
total=(iso(rt['end_date'])-iso(rt['start_date'])).total_seconds();timings.append(['Run complet du 6 décembre',f'{total:.2f} s','19 tâches réussies'])
sections=[]
def section(title,text,*images):
    entries=[]
    for f,c,h in images:
        assert (E/f).is_file(),f
        entries.append({'file':f,'caption':c,'max_height':h})
    sections.append({'title':title,'paragraphs':[text],'images':entries})
section('Préparation et plateforme','Les images prescrites sont installées, les images Airflow et Superset sont construites et les douze services sont démarrés. Trino 484 lit les tables Iceberg existantes. Son interface utilise le port hôte 8084 pour éviter le port 8080 occupé par Steam ; les connexions internes restent sur 8080.',('01-trino-home.png','Étape 1 — Interface réelle de Trino 484.',300),('00-versions-excerpt.png','Versions réellement installées : dbt Core 1.12.7 et adaptateur Trino 1.12.0.',160))
section('Silver quotidien et idempotence','Le JAR Scala fourni est compilé puis exécuté dans Airflow sur le cluster Spark. Le 1er décembre produit 26 826 lignes valides et 695 rejets. Sa répétition remplace exactement les mêmes 26 826 lignes. Le 2 décembre ajoute 26 858 trajets.',('02-silver-01-excerpt.png','Étape 2 — Sortie réelle du job du 1er décembre.',150),('02-snapshots-excerpt.png','Historique Iceberg : création, remplacement de la partition et ajout du 2 décembre.',260))
section('Projet dbt et environnements','Les cibles dev et prod utilisent le même projet SQL, dans gold_dev et gold. Le profil local ne contient pas de mot de passe Trino ; les secrets de production doivent être externalisés.',('03-debug-excerpt.png','Étape 3 — Le diagnostic valide le profil et la connexion.',350))
section('Sources seeds staging et fraîcheur','Deux sources Silver, deux seeds et deux vues de staging sont déclarés. Les huit villes et les sept relevés de carburant sont chargés. La fraîcheur de Silver est PASS.',('04-seed-excerpt.png','Étape 4 — Chargement des deux référentiels.',160),('04-staging-excerpt.png','Création des deux vues de staging.',160),('04-freshness-excerpt.png','Mesure réelle de fraîcheur.',140))
section('Marts et traitement incrémental','Le premier calcul produit 48 lignes, soit deux jours × huit villes × trois routes. Le second passage émet un MERGE de 48 lignes. Le full-refresh reconstruit la table ; le grain demeure unique.',('05-initial-excerpt.png','Étape 5 — Premier calcul des marts.',220),('05-merge-excerpt.png','Second passage incrémental.',170))
section('Tests et blocage des données incorrectes','Seize tests de données et un test unitaire sont exécutés : 16 PASS, un WARN de réconciliation. Les litres du 2 décembre sont 203 513,03 contre 198 832,2 facturés, soit +2,35 %. Le retrait d’Oujda fait échouer 6 739 lignes ; trajets_jour est sauté. Après restauration du seed, le build réussit.',('06-tests-excerpt.png','Étape 6 — Résultat des tests, dont le test unitaire.',200),('06-build-skip-excerpt.png','Échec contrôlé du référentiel et SKIP de la chaîne dépendante.',260))
section('Contrat de données','Le renommage km en km_total est refusé avant écriture. Le SQL est ensuite restauré. Le contrat protège l’interface utilisée par les tableaux de bord.',('07-contract-failure-excerpt.png','Étape 7 — Échec réel du contrat, avec colonne manquante et colonne supplémentaire.',400))
section('Snapshot et lignage','Le snapshot conserve l’ancienne consommation de la Datsun 510 Hatchback à 6,36 l/100 km et la nouvelle à 7,10. Les sources, seeds, staging, marts, snapshot, tests et exposure apparaissent dans dbt docs.',('07-snapshot-history-excerpt.png','Deux versions datées de la même voiture.',150),('07-dbt-lineage.png','Documentation et graphe générés depuis le projet.',390))
section('Connexions et seuil Airflow','Les connexions Spark, Trino et MinIO sont fournies par l’environnement du compose. Le seuil de rejet est une variable lue à l’exécution. Il est restauré à 0,05 après chaque panne.',('08-connection-excerpt.png','Étape 8 — Connexion Trino déclarée hors du DAG.',220),('08-variable-excerpt.png','Valeur réelle du seuil nominal.',120))
section('Orchestration quotidienne','Le test complet pour le 3 décembre termine les 19 tâches avec succès. Le graphe relie attente Bronze, Spark, contrôle qualité, groupe Cosmos puis publication. Les durées du compte rendu utilisent les horodatages des tâches ; cette version de dags test donne au run une date de début historique, impropre à la mesure de son temps réel.',('09-airflow-graph.png','Étape 9 — Graphe Airflow et groupe dbt déplié.',500))
section('Pannes et reprise ciblée','Sans Bronze pour le mois courant, le capteur abandonne et bloque 18 tâches. Deux runs de ce type sont conservés, la préparation ayant traversé minuit UTC. Le 4 décembre, 683 rejets sur 27 695 trajets reçus donnent 2,47 % : deux essais échouent au seuil de 2 %. Gold reste au 3 décembre. Clear du contrôle et de l’aval après retour à 5 % répare le run sans relancer Spark.',('10-quality-failure.png','Étape 10 — Historique de la panne de qualité avant récupération.',390),('10-gold-before-clear-excerpt.png','Gold conserve ses 72 agrégats et 80 575 trajets précédents.',150))
section('Backfill et rejeu complet','Les runs du 5 au 7 décembre sont créés avec max_active_runs=1, puis réussissent. Le rejeu complet du 5 décembre conserve les mêmes totaux en Silver et Gold. Les deux échecs de capteur restent visibles pour garder l’historique.',('11-grid.png','Étape 11 — Grid dépliée avec backfill et reprises réussies.',510))
section('Asset et fichier livré','L’Asset Gold relie la tâche publier au DAG export_trajets. Le Clear de publier déclenche l’export de la dernière journée disponible : un CSV de 24 lignes pour le 7 décembre, remplacé de façon idempotente dans MinIO.',('11-assets.png','Asset producteur et DAG consommateur déclarés dans Airflow.',300),('11-export-csv-excerpt.png','Extrait du fichier effectivement livré ; la sortie complète conserve les 24 lignes.',220))
section('SQL Lab et comparaison des couches','SQL Lab interroge Silver puis Gold. Les sept nombres de trajets sont identiques. La requête Silver du sujet arrondit les kilomètres à l’entier, celle de Gold conserve une décimale ; la validation finale à une décimale trouve exactement les mêmes distances.',('12-sql-gold.png','Étape 12 — Requête Gold exécutée dans SQL Lab, avec ses sept résultats.',490))
section('Métriques et tableau de bord','Les métriques centralisées additionnent les trajets et kilomètres ; la consommation est le rapport pondéré des litres aux kilomètres, multiplié par 100. Elle n’est pas la moyenne des consommations des groupes. Les cinq graphiques et les filtres Région, Type de route et Période sont configurés.',('14-dashboard.png','Étapes 13 et 14 — Tableau de bord complet au 7 décembre : 26 877 trajets pour la dernière journée.',620))
section('Sécurité par ligne','Le compte resp_fes dispose du rôle Gamma et de Region_Fes_Meknes. La clause RLS region = Fès-Meknès limite les requêtes sur trajets_jour : une seule option de région et 6 645 trajets le 7 décembre. Les requêtes SQL capturées confirment le WHERE ajouté. La table conso_modeles reste globale, comme demandé.',('15-dashboard-fes.png','Étape 15 — Même tableau de bord dans une session distincte du responsable régional.',620))
section('Supervision et versionnement','Le tableau de bord de supervision lit les métadonnées PostgreSQL d’Airflow. Les durées sont calculées entre les premières et dernières tâches. Les deux dashboards, les jeux de données, les métriques et les graphiques sont exportés en YAML dans superset/tableaux.',('16-supervision.png','Étape 16 — Durées et runs en échec, consultables dans Superset.',490))
section('Collecte des journaux','Alloy découvre les conteneurs du compose et lit les fichiers de tâches et d’alertes. Les métadonnées run_id et essai restent non indexées ; les étiquettes indexées sont dag_id, level, service, service_name, source et task_id. Les composants transmettent les vrais journaux à Loki.',('17-alloy-graph.png','Étape 17 — Pipeline Alloy avec 10 composants et 9 connexions.',500))
section('Recherche et agrégation LogQL','Les trois recherches et les deux agrégations du sujet sont exécutées avec succès. Explore retrouve les deux essais en échec du 4 décembre, leur reprise, les backfills et le run du 8 décembre. Les taux proviennent du texte des journaux.',('18-logql-taux.png','Étape 18 — Requête LogQL du taux de rejet dans Explore.',500))
section('Détection de la panne finale','Le 8 décembre réussit. Au seuil de 2 %, le 9 décembre échoue deux fois avec 26 797 trajets valides, 643 rejets et un taux de 2,34 %. Gold reste au 8 décembre : 192 agrégats et 214 482 trajets. Le callback écrit l’alerte et Grafana affiche Firing.',('19-quality-task.png','Étape 19 — Deux essais et exception réelle du contrôle.',440))
section('Exploitation et alerte','Grafana regroupe fraîcheur de Gold, alertes, taux de rejet, erreurs par tâche, dernières tâches en échec et journaux. L’alerte compte les lignes du callback dans une fenêtre de dix minutes, avec absence de données considérée normale.',('19-grafana-failure.png','Tableau de bord d’exploitation pendant la panne.',500))
section('Règle en Firing puis récupération','La règle est évaluée chaque minute, sans période d’attente. Après rétablissement du seuil à 5 % et Clear du contrôle avec l’aval, le run du 9 décembre réussit sans nouveau Spark. La règle revient à Normal après expiration de la dernière ligne de sa fenêtre de dix minutes.',('19-alert-firing.png','Règle d’alerte en Firing pendant l’incident.',285),('19-alert-normal.png','Même règle revenue à Normal après récupération.',285))
section('Validation finale','Le build de production réussit : 23 PASS, un WARN de réconciliation, aucune erreur, aucun SKIP et une exposure sans opération. Les 241 279 trajets sont uniques ; les 216 agrégats correspondent à neuf jours × huit villes × trois routes. La fraîcheur est PASS.',('20-final-build-excerpt.png','Construction et tests finaux de production.',260),('20-silver-validation-excerpt.png','Comptage indépendant des neuf journées, sans doublon.',280))
v=dict(chronology_paragraphs=[f'Le run normal du 6 décembre a exécuté ses 19 tâches en <b>{total:.2f} secondes</b>. Airflow attend le Bronze, Spark remplace la partition Silver, le contrôle vérifie le taux de rejet, Cosmos construit et teste Gold puis publier émet l’Asset. Les tâches dbt indépendantes peuvent s’exécuter en parallèle.', 'Les sept premières journées représentent <b>187 875 trajets valides et 168 agrégats Gold</b>. Le CSV livré au partenaire pour le 7 décembre contient 24 lignes. La vue régionale montre 6 645 trajets au lieu de 26 877 pour cette dernière journée.'],normal_run_timings=timings,incident_paragraphs=['<b>Pannes provoquées.</b> Sans Bronze courant, le capteur échoue en environ deux minutes et bloque l’aval. Le seuil de 2 % bloque les 4 et 9 décembre malgré les retries ; le retour à 5 % suivi d’un Clear ciblé répare les runs sans relancer Spark. Le rejeu complet du 5 décembre ne change aucun total.','<b>Qualité métier et observabilité.</b> La réconciliation révèle +2,35 % de litres le 2 décembre et reste en WARN. Alloy transmet les erreurs et alertes à Loki ; Grafana retrouve le taux, la tâche et la journée, affiche Firing, puis Normal après la fenêtre de dix minutes.','<b>État final.</b> Neuf journées, 241 279 trajets uniques et 216 agrégats ; Silver et Gold concordent. Le contrat, la panne de référentiel, le snapshot, la RLS et les exports ont été vérifiés.'],evidence_sections=sections,delivery_paragraphs=['Le dépôt Git local contient le compose, les deux Dockerfile, les configurations Trino, Hive, Spark, PostgreSQL, Superset, Alloy et Grafana, les sources Scala et le JAR, les deux DAG, le projet dbt et les tableaux de bord exportés. Les données Bronze et les volumes de métadonnées sont conservés hors du dépôt.','Le README décrit consommateurs, indicateurs, fraîcheur quotidienne et propriétaire. Les fichiers target et logs de dbt ne sont pas versionnés. L’archive de remise inclut le rapport, le code et les captures originales ; les sorties de commandes et les données de validation sont conservées comme preuves.','La configuration requiert fs.s3.enabled pour Trino 484. Les ports hôtes Trino 8084 et PostgreSQL 5433 évitent les applications déjà présentes. Le profil de démonstration et les mots de passe locaux du sujet ne sont pas destinés à une production.','Les services du TP sont arrêtés en fin de réalisation, sans suppression des volumes et sans arrêt des applications étrangères au TP. Le serveur de documentation dbt s’arrête avec Airflow.'],data=data,normal_run=normal)
(E/'final-validation.json').write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
checklist=json.loads((E/'checklist.json').read_text(encoding='utf-8'))
for x in checklist:x['verified']=True
(E/'checklist.json').write_text(json.dumps(checklist,ensure_ascii=False,indent=2),encoding='utf-8')
(E/'screenshot-map.json').write_text(json.dumps([{'section':s['title'],'images':s['images']} for s in sections],ensure_ascii=False,indent=2),encoding='utf-8')
print('Evidence sections',len(sections),'normal run seconds',total)
